import React, { useState, useEffect } from 'react';
import { Mail, Lock, ArrowRight, X, ArrowLeft, ShieldCheck, Zap, CheckCircle2, Save } from 'lucide-react';

const EntryCard = ({ isOpen, onClose, onLogin }) => {
  const [isFlipped, setIsFlipped] = useState(false);

  // LOGIN VIEWS: 'login', 'forgot', 'reset-password'
  const [loginView, setLoginView] = useState('login'); 
  const [loginOtpSent, setLoginOtpSent] = useState(false); 

  // SIGNUP STATES: 1 = Email/OTP, 2 = Details
  const [signupStep, setSignupStep] = useState(1);
  const [signupOtpSent, setSignupOtpSent] = useState(false);
 const [loginEmail, setLoginEmail] = useState("");
const [loginPassword, setLoginPassword] = useState("");
const [loginError, setLoginError] = useState("");
const isValidEmail = (email) => {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
};   
const handleLogin = async () => {
  setLoginError("");

  // 1. Empty checks
  if (!loginEmail) {
    setLoginError("Email is required");
    return;
  }

  if (!isValidEmail(loginEmail)) {
    setLoginError("Enter a valid email");
    return;
  }

  if (!loginPassword) {
    setLoginError("Password is required");
    return;
  }

  // 2. Backend call
  try {
    const res = await fetch("http://localhost:8080/auth/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        email: loginEmail.trim().toLowerCase(),
        password: loginPassword,
      }),
    });

    const data = await res.json();

    if (!res.ok) {
      throw new Error(data.message || "Login failed");
    }

    // 3. Success
    localStorage.setItem("token", data.token);
    onLogin();

  } catch (err) {
    setLoginError(err.message || "Something went wrong");
  }
};
  useEffect(() => {
    if (!isOpen) {
      setIsFlipped(false);
      setLoginView('login');
      setLoginOtpSent(false);
      setSignupStep(1);
      setSignupOtpSent(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const goToSignup = () => {
    setIsFlipped(true);
    setSignupStep(1);
    setSignupOtpSent(false);
  };

  const goToSignin = () => {
    setIsFlipped(false);
    setLoginView('login');
    setLoginOtpSent(false);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#47510B]/60 backdrop-blur-md p-4 font-sans">
      <div className="flip-container w-full max-w-[400px] h-[600px] animate-slide-up">
        <div className={`flip-inner ${isFlipped ? 'is-flipped' : ''}`}>

          {/* --- FRONT SIDE: SIGN IN / FORGOT / RESET --- */}
          <div className="flip-front bg-[#FDFAD8] border-4 border-[#47510B] rounded-[40px] shadow-[0_20px_0_0_#47510B] p-8 flex flex-col justify-between text-[#47510B]">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2 bg-[#47510B] px-3 py-1 rounded-full text-[#FDFAD8]">
                {loginView === 'login' ? <ShieldCheck size={14} /> : <Zap size={14} />}
                <span className="text-[10px] font-black uppercase tracking-widest">
                  {loginView === 'login' ? 'Secure Entry' : 'Identity Recovery'}
                </span>
              </div>
              <button onClick={onClose} className="hover:rotate-90 transition-transform"><X size={30} /></button>
            </div>

            <div className="mt-4">
              <h2 className="text-4xl font-black uppercase tracking-tighter leading-none">
                {loginView === 'login' && <>welcome<br/>Back!</>}
                {loginView === 'forgot' && <>Verify<br/>Identity</>}
                {loginView === 'reset-password' && <>New<br/>Credentials</>}
              </h2>
            </div>

            {/* 1. STANDARD LOGIN */}
            {loginView === 'login' && (
              <div className="space-y-4">
                <div className="relative">
                  <Mail className="absolute left-4 top-4 opacity-30" size={18} />
                  <input type="email" placeholder="EMAIL ADDRESS" className="w-full bg-white border-2 border-[#47510B] p-4 pl-12 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30" />
                </div>
                <div className="relative">
                  <Lock className="absolute left-4 top-4 opacity-30" size={18} />
                  <input type="password" placeholder="••••••••" className="w-full bg-white border-2 border-[#47510B] p-4 pl-12 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30" />
                </div>
                <button onClick={() => setLoginView('forgot')} className="text-[11px] font-black text-[#AB1717] uppercase tracking-widest ml-1">Forgot Password?</button>
                <button onClick={onLogin} className="w-full bg-[#47510B] text-[#CAD23C] font-black p-5 rounded-2xl flex items-center justify-center gap-3 shadow-[0_6px_0_0_#2A3106] active:translate-y-1 uppercase text-xl italic">
                  Access <ArrowRight size={30} />
                </button>
              </div>
            )}

            {/* 2. FORGOT PASSWORD (OTP STEP) */}
            {loginView === 'forgot' && (
              <div className="space-y-4">
                <input type="email" placeholder="REGISTERED_EMAIL" className="w-full bg-white border-2 border-[#47510B] p-4 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30" />

                {loginOtpSent && (
                  <div className="space-y-3">
                    <label className="text-[10px] font-black uppercase opacity-60 ml-1 text-center block">Enter 4-Digit Node</label>
                    <div className="flex gap-2 justify-between">
                      {[1,2,3,4].map(i => <input key={i} type="text" maxLength="1" className="w-12 h-14 bg-white border-2 border-[#47510B] rounded-xl text-center font-black text-xl" />)}
                    </div>
                  </div>
                )}

                <button 
                  onClick={() => loginOtpSent ? setLoginView('reset-password') : setLoginOtpSent(true)} 
                  className="w-full bg-[#AB1717] text-white font-black p-5 rounded-2xl shadow-[0_6px_0_0_#5E0E0E] active:translate-y-1 uppercase italic"
                >
                  {loginOtpSent ? 'Verify Code' : 'Request OTP'}
                </button>
                <button onClick={() => { setLoginView('login'); setLoginOtpSent(false); }} className="w-full text-center text-[10px] font-black uppercase opacity-60 tracking-widest">Return to Login</button>
              </div>
            )}

            {/* 3. NEW PASSWORD SETTING (FINAL STEP) */}
            {loginView === 'reset-password' && (
              <div className="space-y-4 animate-in fade-in slide-in-from-right-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase opacity-60 ml-1">Secure New Password</label>
                  <input type="password" placeholder="••••••••" className="w-full bg-white border-2 border-[#47510B] p-4 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase opacity-60 ml-1">Confirm New Password</label>
                  <input type="password" placeholder="••••••••" className="w-full bg-white border-2 border-[#47510B] p-4 rounded-2xl font-bold text-sm outline-none focus:ring-4 ring-[#CAD23C]/30" />
                </div>
                <button 
                  onClick={() => setLoginView('login')} 
                  className="w-full bg-[#47510B] text-[#CAD23C] font-black p-5 rounded-2xl shadow-[0_6px_0_0_#2A3106] active:translate-y-1 flex items-center justify-center gap-3 uppercase text-lg italic"
                >
                  Update & Login <Save size={20} />
                </button>
              </div>
            )}

            <div className="text-center pb-2">
              <button onClick={goToSignup} className="font-black text-[15px] tracking-widest uppercase opacity-60 hover:opacity-100">
                No account? <span className="underline decoration-2 underline-offset-4 text-[#AB1717]">Join Tribe</span>
              </button>
            </div>
          </div>

          {/* --- BACK SIDE: SIGN UP (REMAINS AS IS) --- */}
          <div className="flip-back bg-[#FFB6A9] border-4 border-[#AB1717] rounded-[40px] shadow-[0_20px_0_0_#47510B] p-7 flex flex-col h-full text-[#47510B]">
            <div className="flex justify-between items-center mb-4">
               <button onClick={goToSignin} className="flex items-center gap-2 font-black text-[16px] tracking-widest uppercase"><ArrowLeft size={24} /> Back</button>
              <button onClick={onClose} className="text-[#AB1717] hover:rotate-90 transition-transform"><X size={30} /></button>
            </div>

            <div className="mb-4">
              <h2 className="text-4xl font-black text-[#AB1717] uppercase tracking-tighter leading-none">New<br/>Registry</h2>
              <div className="h-1 w-12 bg-[#AB1717] mt-2" />
            </div>

            <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar mb-4">
              {signupStep === 1 ? (
                <div className="space-y-4">
                  <div className="space-y-1">
                    <label className="text-[12px] font-black text-[#AB1717] uppercase tracking-widest ml-1">Email Verification</label>
                    <div className="flex gap-2 w-full">
                      <input type="email" placeholder="EMAIL_ENTRY" className="flex-1 min-w-0 p-4 bg-[#FDFAD8] rounded-xl border-2 border-[#AB1717]/30 font-black uppercase text-[10px] text-[#AB1717] outline-none" />
                      <button onClick={() => setSignupOtpSent(true)} className="bg-[#AB1717] text-white px-4 rounded-xl font-black text-[10px] uppercase shadow-[0_4px_0_0_#5E0E0E] active:translate-y-1">OTP</button>
                    </div>
                  </div>
                  {signupOtpSent && (
                    <div className="space-y-3 pt-2">
                      <div className="flex gap-2 justify-between">
                        {[1,2,3,4].map(i => <input key={i} type="text" maxLength="1" className="w-12 h-14 bg-[#FDFAD8] border-2 border-[#AB1717] rounded-xl text-center font-black" />)}
                      </div>
                      <button onClick={() => setSignupStep(2)} className="w-full bg-[#47510B] text-white py-4 rounded-xl font-black uppercase italic shadow-[0_4px_0_#2A3106] active:translate-y-1">Verify Identity</button>
                    </div>
                  )}
                </div>
              ) : (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 font-black text-[10px] uppercase mb-2"><CheckCircle2 size={16} className="text-green-600" /> Email Verified</div>
                  <input type="text" placeholder="FULL_NAME" className="w-full p-4 bg-[#FDFAD8] rounded-xl border-2 border-[#AB1717]/20 font-black text-xs" />
                  <input type="tel" placeholder="PHONE_NUMBER" className="w-full p-4 bg-[#FDFAD8] rounded-xl border-2 border-[#AB1717]/20 font-black text-xs" />
                  <input type="text" placeholder="RESIDENCE ADDRESS" className="w-full p-4 bg-[#FDFAD8] rounded-xl border-2 border-[#AB1717]/20 font-black text-xs" />
                  <input type="password" placeholder="CREATE_PASSWORD" className="w-full p-4 bg-[#FDFAD8] rounded-xl border-2 border-[#AB1717]/20 font-black text-xs" />
                </div>
              )}
            </div>

            <div className="pt-2">
              <button 
                disabled={signupStep === 1}
                onClick={onLogin} 
                className={`w-full py-4 rounded-2xl font-black uppercase italic text-xl transition-all shadow-[0_5px_0_#5E0E0E] active:translate-y-1 mb-4 
                  ${signupStep === 2 ? 'bg-[#AB1717] text-[#FFB6A9]' : 'bg-[#47510B]/20 text-[#47510B]/40 shadow-none'}`}
              >
                REGISTER CITIZEN
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default EntryCard;
